#include <zephyr/kernel.h>
#include <ksched.h>
#include <zephyr/wait_q.h>

#ifdef CONFIG_USERSPACE
#include <zephyr/arch/riscv/arch.h>
#endif

#if !defined(CONFIG_MULTITHREADING) && defined(CONFIG_RISCV_HAS_FPU)
K_KERNEL_STACK_ARRAY_DECLARE(z_interrupt_stacks, CONFIG_MP_MAX_NUM_CPUS,
			     CONFIG_ISR_STACK_SIZE);
#endif

void z_thread_entry(k_thread_entry_t thread,
		    void *arg1,
		    void *arg2,
		    void *arg3);

void arch_new_thread(struct k_thread *thread, k_thread_stack_t *stack,
		     char *stack_ptr, k_thread_entry_t entry,
		     void *p1, void *p2, void *p3)
{
	extern void z_riscv_thread_start(void);
	struct __esf *stack_init;

#ifdef CONFIG_RISCV_SOC_CONTEXT_SAVE
	const struct soc_esf soc_esf_init = {SOC_ESF_INIT};
#endif

	/* Initial stack frame for thread */
	stack_init = (struct __esf *)Z_STACK_PTR_ALIGN(
				Z_STACK_PTR_TO_FRAME(struct __esf, stack_ptr)
				);

	/* Setup the initial stack frame */
	stack_init->a0 = (unsigned long)entry;
	stack_init->a1 = (unsigned long)p1;
	stack_init->a2 = (unsigned long)p2;
	stack_init->a3 = (unsigned long)p3;

	/*
	 * Following the RISC-V architecture, the MSTATUS register (used to
	 * globally enable/disable interrupts as well asler handle other
	 * processor states) is restored from the stack upon returning from an
	 * ISR (via mret). Therefore, we must set the initial MSTATUS value
	 * for a new thread:
	 * - MPIE bit set to 1: restore interrupts enabled upon mret
	 * - MPP bits set to M-mode (11) or U-mode (00)
	 * - FS bits set to Initial (01) if FPU is enabled
	 */
	stack_init->mstatus = MSTATUS_DEF_RESTORE;
#if defined(CONFIG_FPU) && defined(CONFIG_FPU_SHARING)
	if ((thread->base.user_options & K_FP_REGS) != 0) {
		stack_init->mstatus |= MSTATUS_FS_INIT;
	}
	thread->arch.exception_depth = 0;
#elif defined(CONFIG_FPU)
	/* Unshared FP mode: enable FPU of each thread. */
	stack_init->mstatus |= MSTATUS_FS_INIT;
#endif

#ifdef CONFIG_USERSPACE
	if ((thread->base.user_options & K_USER) != 0) {
		stack_init->mepc = (unsigned long)k_thread_user_mode_enter;
	} else {
		stack_init->mepc = (unsigned long)z_thread_entry;
	}
#if defined(CONFIG_PMP_STACK_GUARD)
	z_riscv_pmp_stackguard_prepare(thread);
#endif /* CONFIG_PMP_STACK_GUARD */
	z_riscv_pmp_usermode_init(thread);
#else
	stack_init->mepc = (unsigned long)z_thread_entry;
#if defined(CONFIG_PMP_STACK_GUARD)
	z_riscv_pmp_stackguard_prepare(thread);
#endif /* CONFIG_PMP_STACK_GUARD */
#endif /* CONFIG_USERSPACE */

#ifdef CONFIG_RISCV_SOC_CONTEXT_SAVE
	stack_init->soc_context = soc_esf_init;
#endif

#if defined(CONFIG_CLIC) && defined(CONFIG_RISCV_ALWAYS_SWITCH_THROUGH_ECALL)
	/* Clear mcause Pil (Previous interrupt level) field */
	stack_init->mcause = 0;
#endif

	/* where to go when returning from z_riscv_switch() */
	thread->callee_saved.ra = (unsigned long)z_riscv_thread_start;

	/* our switch handle is the thread pointer itself */
	thread->switch_handle = thread;

	/* stack pointer after popping callee-saved registers */
	thread->callee_saved.sp = (unsigned long)stack_init;
}

#ifdef CONFIG_USERSPACE

/*
 * User space entry function
 *
 * This function is the entry point to user mode from privileged execution.
 * The conversion is one way, and threads which enter user mode do not
 * transition back later, unless they are doing system calls.
 */
FUNC_NORETURN void arch_user_mode_enter(k_thread_entry_t user_entry,
					void *p1, void *p2, void *p3)
{
	unsigned long top_of_user_stack = 0UL;
	uintptr_t status;

	/* Set up privileged stack */
#ifdef CONFIG_GEN_PRIV_STACKS
	_current->arch.priv_stack_start =
			(unsigned long)z_priv_stack_find(_current->stack_obj);
	/* remove the stack guard from the main stack */
	_current->arch.priv_stack_start += K_KERNEL_STACK_RESERVED;
#else
	_current->arch.priv_stack_start =
			(unsigned long)(_current->stack_info.start -
					CONFIG_PRIVILEGED_STACK_SIZE);
#endif /* CONFIG_GEN_PRIV_STACKS */

	top_of_user_stack = Z_STACK_PTR_ALIGN(
				_current->stack_info.start +
				_current->stack_info.size -
				_current->stack_info.delta);

	status = csr_read(mstatus);
	status = INSERT_FIELD(status, MSTATUS_MPP, PRV_U);
	status = INSERT_FIELD(status, MSTATUS_MPIE, 1);

	csr_write(mstatus, status);
	csr_write(mepc, z_thread_entry);

	/* Set up PMP for user mode */
	z_riscv_pmp_usermode_prepare(_current);
	z_riscv_pmp_usermode_enable(_current);

#ifdef CONFIG_PMP_STACK_GUARD
	/* Now that we are going to usermode, we need to protect the
	 * privilege stack with the PMP stackguard.
	 */
	z_riscv_pmp_stackguard_prepare(_current);
	z_riscv_pmp_stackguard_enable(_current);
#endif /* CONFIG_PMP_STACK_GUARD */

	arch_riscv_user_mode_enter(user_entry, p1, p2, p3, top_of_user_stack,
				   _current->arch.priv_stack_start +
				   CONFIG_PRIVILEGED_STACK_SIZE);
	CODE_UNREACHABLE;
}

#endif /* CONFIG_USERSPACE */

#ifndef CONFIG_MULTITHREADING

K_KERNEL_STACK_ARRAY_DECLARE(z_interrupt_stacks, CONFIG_MP_MAX_NUM_CPUS, CONFIG_ISR_STACK_SIZE);
K_THREAD_STACK_DECLARE(z_main_stack, CONFIG_MAIN_STACK_SIZE);

FUNC_NORETURN void z_riscv_switch_to_main_no_multithreading(k_thread_entry_t main_entry,
							    void *p1, void *p2, void *p3)
{
	void *main_stack;

	ARG_UNUSED(p1);
	ARG_UNUSED(p2);
	ARG_UNUSED(p3);

	main_stack = (K_THREAD_STACK_BUFFER(z_main_stack) +
		      K_THREAD_STACK_SIZEOF(z_main_stack));

	main_stack = (void *)Z_STACK_PTR_ALIGN((uintptr_t)main_stack);

#ifdef CONFIG_RISCV_HAS_FPU
	/* Initialize the FPU & enable the IRQ in MSTATUS */
	csr_write(mstatus, MSTATUS_DEF_RESTORE | MSTATUS_FS_INIT);

	/* Set Scratch Register to the IRQ stack, prior to switching to the main stack */
	void *isr_stack = (K_KERNEL_STACK_BUFFER(z_interrupt_stacks[0]) +
			   K_KERNEL_STACK_SIZEOF(z_interrupt_stacks[0]));

	isr_stack = (void *)Z_STACK_PTR_ALIGN((uintptr_t)isr_stack);
	csr_write(mscratch, isr_stack);
#else
	/* Enable the IRQ in MSTATUS */
	csr_write(mstatus, MSTATUS_DEF_RESTORE);
#endif /* CONFIG_RISCV_HAS_FPU */

	__asm__ volatile (
		"mv sp, %0\n"
		"jalr ra, %1, 0"
		: : "r" (main_stack), "r" (main_entry)
	);

	/* Infinite loop */
	irq_lock();
	while (true) {
	}

	CODE_UNREACHABLE;
}
#endif /* !CONFIG_MULTITHREADING */

#if defined(CONFIG_FPU) && defined(CONFIG_FPU_SHARING)
int arch_float_disable(struct k_thread *thread)
{
	unsigned int key;

	if (thread != _current) {
		return -EINVAL;
	}

	if (arch_is_in_isr()) {
		return -EINVAL;
	}

	/* Ensure a preemptive context switch does not occur */
	key = irq_lock();

	/* Disable all floating point capabilities for the thread */
	thread->base.user_options &= ~K_FP_REGS;

	/* Clear the FS bits to disable the FPU. */
	__asm__ volatile (
		"li t0, %0\n"
		"csrc mstatus, t0\n"
		:
		: "i" (MSTATUS_FS_MASK)
		: "t0"
	);

	irq_unlock(key);

	return 0;
}

int arch_float_enable(struct k_thread *thread, unsigned int options)
{
	unsigned int key;

	if (thread != _current) {
		return -EINVAL;
	}

	if (arch_is_in_isr()) {
		return -EINVAL;
	}

	/* Ensure a preemptive context switch does not occur */
	key = irq_lock();

	/* Enable all floating point capabilities for the thread. */
	thread->base.user_options |= K_FP_REGS;

	/* Set the FS bits to Initial to enable the FPU. */
	__asm__ volatile (
		"li t0, %0\n"
		"csrs mstatus, t0\n"
		:
		: "i" (MSTATUS_FS_INIT)
		: "t0"
	);

	irq_unlock(key);

	return 0;
}
#endif /* CONFIG_FPU && CONFIG_FPU_SHARING */
